import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&/^(arrmidi|clearrange)_/.test(w))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text)}catch{}walk(v);return v}
const one={trackRef:'track:track-1',start:8,length:4,notes:[{pitch:60,start:0,duration:1}]};
const variants={single:one,named:{...one,name:'Test',looping:true,notes:[{pitch:64,start:1,duration:0.001,velocity:91.25,mute:false,probability:0.5,velocityDeviation:-4.5,releaseVelocity:32.5}]},empty:{...one,notes:[]},group:{clips:[one,{...one,start:16,name:'Two'}]},tracks:{clips:[one,{...one,trackRef:'track:track-2'}]},clear:{trackRef:one.trackRef,fromBeat:8,toBeat:12},cut:{trackRef:one.trackRef,fromBeat:9,toBeat:11}};
const seeds={};for(const kind of Object.keys(variants)){const sim=new DeterministicLiveSimulator();if(kind==='tracks'){const second={...structuredClone(sim.state.tracks[0]),ref:'track:track-2',objectIdentity:'simulator:track:2',name:'Keys',index:1,devices:[],clips:[],clipSlots:[]};sim.state.tracks.push(second);}if(['clear','cut'].includes(kind))sim.invoke({operation:'arrangement.midi-clip.create',args:{...one,name:'There'}});seeds[kind]=structuredClone(sim.state)}
const rows=[];for(const kind of ['single','clear'])for(const action of ['preview','apply']){const valid=action==='preview'?variants[kind]:{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-1,0,0.0001,0.001,0.5,1,'','x','a'.repeat(257)])cases.push({...valid,[key]:value})}if(kind==='single'&&action==='preview'){
for(const key of ['name','looping'])for(const value of [null,'',false,true,0,1,'x','😀'.repeat(128),'a'.repeat(257)])cases.push({...one,[key]:value});
for(const key of ['pitch','start','duration','velocity','mute','probability','velocityDeviation','releaseVelocity','extra'])for(const value of [null,[],{},false,true,-128,-127,-0.1,0,0.0001,0.001,0.5,1,4,127,128,'x'])cases.push({...one,notes:[{...one.notes[0],[key]:value}]});
for(const clips of [null,[],{},[one],[one,{...one,start:10}],[one,{...one,start:12}], [one,null], [one,{...one,trackRef:''}]])cases.push({clips});}
for(const p of cases){const sim=new DeterministicLiveSimulator(),host=new McpHost(sim);let result;try{result=clean(await host[(kind==='single'?'liveArrangementMidiClip':'liveClipClearRange')+(action==='preview'?'PreviewAsync':'ApplyAsync')](1,p))}catch(e){result={error:e.message}}rows.push({kind,action,args:p,result})}}
const workflows=[];for(const kind of Object.keys(variants))for(const scenario of ['normal','expire','epoch','identity-edit','clips-edit','missing-identity','group-track','audio-track','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','apply-partial','apply-partial-timeout','apply-unreported-partial','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-identity','undo-name','undo-start','undo-length','undo-notes','undo-epoch']){
const sim=new DeterministicLiveSimulator();Object.assign(sim.state,structuredClone(seeds[kind]));const calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false;if(scenario==='missing-identity')sim.state.tracks[0].objectIdentity='';if(scenario==='group-track')sim.state.tracks[0].kind='group';if(scenario==='audio-track')sim.state.tracks[0].mediaKind='audio';
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure')}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return structuredClone(cache.get(key));if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure')}
if(!fired&&i.operation==='transaction.group'&&['apply-partial','apply-partial-timeout','apply-unreported-partial'].includes(fault)){fired=true;afterInvoke=true;sim.invoke(i.args.ops[0]);if(fault==='apply-unreported-partial')return {ok:true};throw Error(fault==='apply-partial'?'step 2 failed (refused)':'injected operation failure')}
const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else if(i.operation==='arrangement.clip.delete')cache.set(key,structuredClone(result));afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure')}return result}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async c=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const method=['clear','cut'].includes(kind)?'liveClipClearRange':'liveArrangementMidiClip';const preview=await host[method+'PreviewAsync'](1,variants[kind]);results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const p={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host[method+'ApplyAsync'](results.length+1,p,controller.signal):await host.liveUndoAsync(results.length+1,p)));states.push(clean(record))}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')sim.state.tracks[0].objectIdentity='other';if(scenario==='clips-edit')sim.invoke({operation:'arrangement.midi-clip.create',args:{...one,start:40}});if(scenario.startsWith('apply-')){fault=scenario;fired=false;afterInvoke=false;}
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
const created=sim.state.arrangementClips?.find(c=>c.clip.objectIdentity===record.created?.clips?.[0]?.objectIdentity)?.clip;if(created){if(scenario==='undo-other-identity')created.objectIdentity='other';if(scenario==='undo-name')created.name='Manual';if(scenario==='undo-start')created.start+=1;if(scenario==='undo-length')created.length+=1;if(scenario==='undo-notes')created.notes[0]?created.notes[0].pitch=72:created.notes.push({pitch:72,start:0,duration:1,velocity:100,mute:false,channel:1,id:700});}if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-name','undo-start','undo-length','undo-notes','undo-epoch'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key')}
workflows.push({kind,scenario,results,states,calls,state:sim.state})}
fs.writeFileSync(new URL('host-arrangement-midi-oracle.json',import.meta.url),JSON.stringify({seeds,variants,rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
